CREATE SEQUENCE dbo.DispatchNumber
    AS bigint START WITH 700 INCREMENT BY 1;
GO
BEGIN TRANSACTION;
DECLARE @reserved bigint = NEXT VALUE FOR dbo.DispatchNumber;
ROLLBACK TRANSACTION;
SELECT NEXT VALUE FOR dbo.DispatchNumber AS FollowingNumber;

CREATE SEQUENCE dbo.PairNumber AS int
    START WITH 40 INCREMENT BY 5 NO CACHE;
GO
SELECT NEXT VALUE FOR dbo.PairNumber AS LeftNo,
       NEXT VALUE FOR dbo.PairNumber AS RightNo;
SELECT NEXT VALUE FOR dbo.PairNumber AS AfterNo;
